def check_k_colors(n, k):
    # Use backtracking to see if k colors are possible
    grid = [[0]*n for _ in range(n)]

    def solve(r, c, colors_used):
        if r == n:
            return True

        next_r, next_c = (r, c + 1) if c < n - 1 else (r + 1, 0)

        # Try using a new color if we haven't reached k
        if len(colors_used) < k:
            new_color = len(colors_used)
            grid[r][c] = new_color
            if r == 0 or c == 0 or len({grid[r-1][c-1], grid[r-1][c], grid[r][c-1], grid[r][c]}) <= 3:
                if solve(next_r, next_c, colors_used | {new_color}):
                    return True

        # Try using an existing color
        for color in colors_used:
            grid[r][c] = color
            if r == 0 or c == 0 or len({grid[r-1][c-1], grid[r-1][c], grid[r][c-1], grid[r][c]}) <= 3:
                if solve(next_r, next_c, colors_used):
                    return True
        return False

    return solve(0, 0, set())

