import random

def get_score(grid, n):
    # Number of 2x2 blocks with 4 distinct colors
    score = 0
    for i in range(n - 1):
        for j in range(n - 1):
            if len({grid[i][j], grid[i+1][j], grid[i][j+1], grid[i+1][j+1]}) == 4:
                score += 1
    return score

def find_max_colors_simulated_annealing(n, k):
    # Try to find a coloring with k colors that has score 0
    grid = [[random.randint(0, k-1) for _ in range(n)] for _ in range(n)]
    current_score = get_score(grid, n)

    for i in range(100000):
        if current_score == 0:
            return True

        r, c = random.randint(0, n-1), random.randint(0, n-1)
        old_val = grid[r][c]
        new_val = random.randint(0, k-1)

        grid[r][c] = new_val
        new_score = get_score(grid, n)

        if new_score < current_score:
            current_score = new_score
        elif random.random() < 0.01: # Simple annealing
            current_score = new_score
        else:
            grid[r][c] = old_val

    return False

for k in range(16, 0, -1):
    if find_max_colors_simulated_annealing(4, k):
        print(f"n=4, k={k} is possible")
        break

